mapper.select:
select u.user_id, u.dept_id, u.nick_name, u.user_name, u.email, u.avatar, u.phoneNumber,
       u.password, u.sex, u.status, u.del_flag, u.login_ip, u.login_date, u.create_by,u.place,
       u.idcard,u.personalProfile,u.contact,u.ch_name,u.parent_id,u.weComId,
       u.create_time, u.remark, d.dept_name, d.leader,u.parent_id,u.user_type,u.is_blacklist,
       lu.nick_name as carrierName
from VRS_user u
left join VRS_dept d on u.dept_id = d.dept_id
left join VRS_user lu on u.parent_id = lu.user_id
left join VRS_user_role ur on u.user_id = ur.user_id
left join VRS_role r on r.role_id = ur.role_id
where u.del_flag = '0'

    AND u.user_id = #{userId}


    AND u.user_name like concat('%', #{userName}, '%')


    AND r.role_id =#{roleId}


    AND r.role_id !=144 AND r.role_id !=143 AND r.role_id !=150



    AND u.user_type = #{userType}


    AND u.status = #{status}


    AND u.is_blacklist = #{isBlacklist}


    AND u.parent_id = #{parentId}


    AND u.phoneNumber like concat('%', #{phoneNumber}, '%')



    AND u.is_blacklist =#{isBlacklist}


    AND date_format(u.create_time,'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')


    AND date_format(u.create_time,'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')


    AND (u.dept_id = #{deptId} OR u.dept_id IN ( SELECT t.dept_id FROM VRS_dept t WHERE find_in_set(#{deptId}, ancestors) ))


${params.dataScope}

select distinct u.user_id, u.dept_id, u.user_name, u.nick_name, u.email, u.phoneNumber, u.status, u.create_time,u.user_type,u.is_blacklist from VRS_user u left join VRS_dept d on u.dept_id = d.dept_id left join VRS_user_role ur on u.user_id = ur.user_id left join VRS_role r on r.role_id = ur.role_id where u.del_flag = '0' and r.role_id = #{roleId}
AND u.user_name like concat('%', #{userName}, '%')
AND u.phoneNumber like concat('%', #{phoneNumber}, '%')
${params.dataScope}

mapper.update:
update VRS_user
dept_id = #{deptId}, user_name = #{userName}, nick_name = #{nickName}, email = #{email}, is_blacklist = #{isBlacklist}, parent_id = #{parentId}, phoneNumber = #{phoneNumber}, sex = #{sex}, user_type = #{userType}, avatar = #{avatar}, password = #{password}, status = #{status}, login_ip = #{loginIp}, login_date = #{loginDate}, update_by = #{updateBy}, remark = #{remark}, qqNumber = #{qqNumber}, personalProfile=#{personalProfile}, place=#{place}, idcard=#{idcard}, contact=#{contact}, ch_name=#{chName}, weComId=#{weComId}, update_time = sysdate()
where user_id = #{userId}
